// === Format the Discord alert + classify severity ===
const e = $input.first().json;
const wf       = e.workflow ? e.workflow.name : 'unknown workflow';
const execId   = e.execution ? e.execution.id : 'n/a';
const execUrl  = e.execution && e.execution.url ? e.execution.url : '';
const lastNode = e.execution && e.execution.lastNodeExecuted
  ? e.execution.lastNodeExecuted : 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message)
  ? e.execution.error.message : 'No message';

// Partial-success case: blog draft created but newsletter email failed.
let tier = '\uD83D\uDFE0 [WORKFLOW] Pipeline run failed.';
if (lastNode === 'Email newsletter draft to the host')
  tier = '\uD83D\uDFE0 [WORKFLOW - PARTIAL] Blog draft was created but the newsletter '
       + 'email failed. Episode NOT marked done -- it will retry next run.';
else if (lastNode === 'Retry cap alert')
  tier = '\uD83D\uDD34 [STUCK EPISODE] Retry cap hit -- needs manual attention. Will not retry again.';

const content = tier
  + '\n**Workflow:** ' + wf
  + '\n**Failed node:** ' + lastNode
  + '\n**Error:** ' + msg
  + '\n**Execution:** ' + (execUrl || execId)
  + '\n**Time:** ' + new Date().toISOString();

return [{ json: { content } }];
